# Multi-radius results against DIRECT pinned-PST evidence (tests/testthat/fixtures/angular-multi-radius-direct-v3.3.2.R, generated by
# tools/reference/angular/generate-multi-radius-reference.py from the pinned exported C API, one native call per radius and the
# exported normalisers; no rPSTool analysis is involved). Same comparison policy as test-angular-controls.R.

mrd_compare <- function(actual, expected) {
  expected <- as.double(unlist(expected))
  expect_identical(is.nan(actual), is.nan(expected))
  expect_identical(is.infinite(actual), is.infinite(expected))
  expect_identical(actual[!is.finite(expected)], expected[!is.finite(expected)])
  expect_equal(actual[is.finite(expected)], expected[is.finite(expected)], tolerance = 3e-6)
  sum(!is.finite(expected))
}
mrd_code <- c(straight = "s", walking = "w", steps = "n", angular = "a")

test_that("multi-radius and multi-normalisation columns equal the direct pinned-PST results", {
  ref <- dget(test_path("fixtures", "angular-multi-radius-direct-v3.3.2.R"))
  expect_identical(ref$pst_commit, unname(rPSTool:::.pst_engine_pin()[["pst_commit"]]))
  old <- Sys.getenv("RPST_NUM_THREADS", unset = NA_character_)
  Sys.setenv(RPST_NUM_THREADS = "1")
  on.exit(if (is.na(old)) Sys.unsetenv("RPST_NUM_THREADS") else Sys.setenv(RPST_NUM_THREADS = old), add = TRUE)
  graphs <- lapply(ref$graphs, function(x) segment_graph(matrix(unlist(x), ncol = 4, byrow = TRUE)))
  expect_identical(length(ref$families), 120L)   # the fixture is complete whichever subset is visited
  nonfinite <- 0
  nonfinite_graphs <- character()
  seen <- character()
  # CRAN mode: every routine x weighting x varied radius type, every graph x routine, every angle threshold and precision, plus every
  # 10th family; full mode compares all 120 families.
  for (fam in rpst_cases(ref$families, every = 10L,
                         by = list(function(f) paste(f$routine, f$weighted, f$vary), function(f) paste(f$graph, f$routine),
                                   function(f) f$threshold, function(f) f$precision))) {
    g <- graphs[[fam$graph]]
    radius <- do.call(analysis_radius, c(fam$fixed, setNames(list(unlist(fam$values)), fam$vary)))
    norms <- if (fam$routine == "integration") c("turner", "syntax", "hillier") else c("standard", "turner", "syntax")
    out <- if (fam$routine == "integration")
      angular_integration(g, radius = radius, weigh_by_length = fam$weighted, normalization = norms,
                              angle_threshold = fam$threshold, angle_precision = fam$precision, weight_outputs = TRUE)
    else
      angular_choice(g, radius, weigh_by_length = fam$weighted, normalization = norms,
                         angle_threshold = fam$threshold, angle_precision = fam$precision)
    seen <- c(seen, paste(fam$routine, fam$weighted, fam$vary))
    before <- nonfinite
    expect_identical(names(out)[1L], "segment_id")
    expect_identical(ncol(out), 1L + length(fam$values) * (if (fam$routine == "integration") 3L + 4L else 3L + fam$weighted + 3L))
    for (i in seq_along(fam$values)) {
      run <- fam$runs[[i]]
      tag <- paste0("_", mrd_code[[fam$vary]], rPSTool:::.pst_radius_value_text(fam$values[[i]], fam$vary == "steps"))
      col <- function(base) out[[paste0(base, tag)]]
      expect_identical(col("node_count"), as.integer(unlist(run$counts)))
      nonfinite <- nonfinite + mrd_compare(col("total_depth"), run$depths)
      if (fam$routine == "integration") {
        for (n in norms) nonfinite <- nonfinite + mrd_compare(out[[paste0("integration_", n, tag)]], run$normalized[[n]])
        nonfinite <- nonfinite + mrd_compare(col("total_weight"), run$weights)          # present although weigh_by_length may be FALSE
        nonfinite <- nonfinite + mrd_compare(col("total_depth_weight"), run$depth_weights)
      } else {
        nonfinite <- nonfinite + mrd_compare(col("choice"), run$scores)
        for (n in norms) nonfinite <- nonfinite + mrd_compare(out[[paste0("choice_", n, tag)]], run$normalized[[n]])
        if (fam$weighted) nonfinite <- nonfinite + mrd_compare(col("total_depth_weight"), run$depth_weights)
        else expect_null(col("total_depth_weight"))
      }
    }
    if (nonfinite > before) nonfinite_graphs <- c(nonfinite_graphs, fam$graph)
  }
  # the cases requested for evidence are really in the fixture, and native NaN/Inf were compared (not vacuous)
  expect_true(all(c("choice TRUE walking", "choice TRUE steps", "integration FALSE walking", "integration TRUE straight") %in% seen))
  expect_gt(nonfinite, 0)
  expect_identical(unique(nonfinite_graphs), "large_star")   # genuine native NaN/Inf come only from the 4e18-coordinate star
})

test_that("native NaN/Inf survive the file route of a multi-radius call unchanged", {
  skip_if_not_installed("sf")
  dir <- so_dir(); on.exit(unlink(dir, recursive = TRUE))
  ref <- dget(test_path("fixtures", "angular-multi-radius-direct-v3.3.2.R"))
  m <- matrix(unlist(ref$graphs$large_star), ncol = 4, byrow = TRUE)
  src <- file.path(dir, "star.fgb")
  sf::st_write(so_sf(m, data.frame(id = seq_len(nrow(m))), epsg = 32630L), src, driver = "FlatGeobuf", quiet = TRUE)
  g <- segment_graph(src)
  radius <- analysis_radius(walking = c(1e19, 6e18))
  frame <- rPSTool::angular_integration(g, radius = radius, weigh_by_length = TRUE, normalization = c("hillier", "turner"))
  nonfinite_cols <- setdiff(names(frame)[vapply(frame, function(x) any(!is.finite(x)), NA)], "segment_id")
  expect_true("ai_a_rw10000000000000000000_wl_h" %in% nonfinite_cols)
  out <- file.path(dir, "out.fgb")
  angular_integration(g, radius = radius, weigh_by_length = TRUE, normalization = c("hillier", "turner"), spatial_output_file = out)
  back <- sf::st_drop_geometry(sf::st_read(out, quiet = TRUE))
  for (nm in setdiff(names(frame), "segment_id")) {
    expect_identical(is.nan(back[[nm]]), is.nan(frame[[nm]]))
    expect_identical(is.infinite(back[[nm]]), is.infinite(frame[[nm]]))
    expect_equal(as.numeric(back[[nm]]), as.numeric(frame[[nm]]), tolerance = 0)
  }
})
